insert into public.recipes (id, name, image_url, cook_time_min, difficulty, servings, calories_est, steps, tags, required_tools, source, is_active) values
('bf43592b-b989-5485-ab6e-29e311cc0b6d', '된장찌개', null, 10, 'NORMAL', 2, 180, '["쌀뜨물이나 물에 된장을 체에 걸러 풀고 중불로 끓인다.","애호박을 반달 모양으로 썰어 넣고 5분간 끓인다.","두부를 깍둑썰기 해서 넣고 3분 더 끓인다.","어슷 썬 대파를 넣고 한소끔 끓인 뒤 간을 맞춰 마무리한다."]'::jsonb, '{한식,집밥}', '{냄비}', 'NaengPago Seed v1', true),
('4eee5d6c-aa04-5488-ac59-a2fea88590db', '김치찌개', null, 15, 'EASY', 2, 250, '["돼지고기를 한입 크기로 썰어 냄비에 넣고 중불에서 겉면을 볶는다.","잘 익은 김치를 썰어 넣고 함께 5분간 볶아 감칠맛을 낸다.","물을 자작하게 붓고 뚜껑을 덮어 15분간 끓인다.","두부를 도톰하게 썰어 넣고 5분 더 끓인다.","어슷 썬 대파를 올리고 간을 맞춰 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('e64cd3c8-6bfb-528c-a57f-1081a5d09b54', '순두부찌개', null, 20, 'EASY', 2, 200, '["달군 냄비에 고춧가루와 기름을 넣고 약불에서 볶아 고추기름을 낸다.","물을 붓고 끓으면 순두부를 큼직하게 떠 넣는다.","중불에서 5분간 끓여 간을 맞춘다.","달걀을 깨 넣고 반숙으로 익힌다.","어슷 썬 대파를 올려 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('f302e76e-2b74-57b2-a6b9-347e252b0356', '부대찌개', null, 25, 'EASY', 2, 350, '["햄과 소시지를 먹기 좋게 썰고 김치는 한입 크기로 썬다.","냄비에 김치, 햄, 소시지, 두부를 보기 좋게 담는다.","육수를 재료가 잠기도록 붓고 센 불에서 끓인다.","끓어오르면 중불로 줄여 10분간 끓여 재료를 익힌다.","간을 확인하고 부족하면 소금으로 맞춰 마무리한다."]'::jsonb, '{한식,집밥}', '{냄비}', 'NaengPago Seed v1', true),
('28c531f4-856c-55c8-ab94-825a58ee741a', '미역국', null, 30, 'EASY', 2, 120, '["불린 미역을 먹기 좋은 길이로 자른다.","냄비에 참기름을 두르고 소고기와 미역을 넣어 중불에서 볶는다.","물을 붓고 센 불에서 끓이다가 끓어오르면 중약불로 줄인다.","뚜껑을 덮고 20분간 끓여 미역을 부드럽게 익힌다.","국간장으로 간을 맞춰 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('e8eb6078-d9cb-52b0-a38d-8e0a6fa85703', '소고기무국', null, 35, 'EASY', 2, 150, '["무를 나박하게 썰고 소고기는 한입 크기로 썬다.","냄비에 소고기와 무를 넣고 중불에서 볶는다.","물을 붓고 센 불에서 끓이다가 거품을 걷어낸다.","중불로 줄여 무가 투명해질 때까지 15분간 끓인다.","국간장으로 간하고 어슷 썬 대파를 넣어 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('47d47c65-02f8-5493-a599-848e439f3167', '북엇국', null, 40, 'EASY', 2, 140, '["북어채를 물에 살짝 불려 물기를 짠다.","냄비에 참기름을 두르고 북어와 채 썬 무를 볶는다.","물을 붓고 중불에서 10분간 끓여 뽀얀 국물을 낸다.","풀어둔 달걀을 돌려 넣고 저어 익힌다.","어슷 썬 대파를 넣고 소금으로 간해 마무리한다."]'::jsonb, '{한식,집밥}', '{냄비}', 'NaengPago Seed v1', true),
('91716fd3-12e2-5178-ab84-acf6fa3be4c6', '콩나물국', null, 10, 'EASY', 2, 60, '["콩나물을 깨끗이 씻어 꼬리를 다듬는다.","냄비에 물과 콩나물을 넣고 뚜껑을 덮어 센 불에서 끓인다.","끓기 시작하면 뚜껑을 열지 않고 5분간 더 끓인다.","다진 마늘을 넣고 소금으로 간을 맞춘다.","어슷 썬 대파를 올려 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('bc9adc24-821d-5558-a35f-c0a8bb4a28ea', '계란국', null, 15, 'EASY', 2, 90, '["냄비에 물을 붓고 국간장으로 간을 맞춰 끓인다.","달걀을 곱게 풀어 준비한다.","국물이 끓으면 달걀물을 가늘게 돌려 넣는다.","젓지 않고 잠시 두었다가 부드럽게 저어 익힌다.","어슷 썬 대파를 올려 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('616adc37-8a9b-5936-ae16-887c5ebb8d5b', '떡국', null, 20, 'NORMAL', 2, 350, '["떡국떡을 찬물에 30분간 담가 불린다.","육수를 끓이고 불린 떡을 넣는다.","떡이 떠오를 때까지 중불에서 5분간 끓인다.","풀어둔 달걀을 돌려 넣어 익힌다.","어슷 썬 대파를 넣고 그릇에 담아 김가루를 올려 마무리한다."]'::jsonb, '{한식,집밥}', '{냄비}', 'NaengPago Seed v1', true),
('8cbd7be7-cf23-5ef3-afd4-1105e2765c3d', '제육볶음', null, 25, 'EASY', 2, 400, '["고추장, 고춧가루, 간장, 설탕으로 양념장을 만든다.","돼지고기에 양념장을 넣고 20분간 재운다.","달군 팬에 재운 고기를 넣고 센 불에서 볶는다.","고기가 익으면 채 썬 양파를 넣고 함께 볶는다.","어슷 썬 대파를 넣고 살짝 더 볶아 마무리한다."]'::jsonb, '{집밥}', '{프라이팬}', 'NaengPago Seed v1', true),
('55fdd92b-7a41-5718-a08f-2ba6ee038e58', '소불고기', null, 30, 'EASY', 2, 350, '["간장, 설탕, 다진 마늘, 참기름으로 양념장을 만든다.","얇게 썬 소고기를 양념장에 30분간 재운다.","채 썬 양파를 양념 고기에 섞는다.","달군 팬에 고기를 펼쳐 센 불에서 볶는다.","고기가 익으면 어슷 썬 대파를 넣고 살짝 볶아 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('1faa32f2-08d1-5613-ae20-679a2c0c9c0f', '닭볶음탕', null, 35, 'EASY', 2, 450, '["닭고기를 끓는 물에 살짝 데쳐 기름기를 뺀다.","고추장, 고춧가루, 간장으로 양념장을 만든다.","냄비에 닭과 양념장, 물을 넣고 센 불에서 끓인다.","감자와 당근을 큼직하게 썰어 넣는다.","중불로 줄여 국물이 자작해질 때까지 25분간 조린다."]'::jsonb, '{한식,집밥}', '{프라이팬}', 'NaengPago Seed v1', true),
('5f5f8f80-0a45-5917-a8d3-a8c03ad58120', '찜닭', null, 40, 'EASY', 2, 500, '["당면을 미지근한 물에 30분간 불린다.","닭고기를 데쳐 기름기를 제거한다.","간장, 설탕, 물로 양념을 만들어 닭과 함께 끓인다.","감자를 큼직하게 썰어 넣고 15분간 조린다.","불린 당면을 넣고 국물이 배도록 5분 더 익혀 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('71d1e68e-60c9-5adc-a496-a8797b5b44fb', '오징어볶음', null, 10, 'EASY', 2, 300, '["오징어를 손질해 먹기 좋은 크기로 칼집을 넣어 썬다.","고추장, 고춧가루, 간장으로 양념장을 만든다.","달군 팬에 채 썬 양파를 센 불에서 볶는다.","오징어와 양념장을 넣고 빠르게 볶는다.","오징어가 익으면 어슷 썬 대파를 넣고 마무리한다."]'::jsonb, '{집밥}', '{프라이팬}', 'NaengPago Seed v1', true),
('574697b3-7bd3-51f7-a2c8-d36d60a4d13f', '낙지볶음', null, 15, 'EASY', 2, 280, '["낙지를 밀가루로 주물러 씻어 물기를 뺀다.","고춧가루, 고추장, 간장으로 매운 양념장을 만든다.","달군 팬에 양파를 볶다가 낙지를 넣는다.","양념장을 넣고 센 불에서 빠르게 볶는다.","어슷 썬 대파를 넣고 낙지가 질겨지지 않게 바로 마무리한다."]'::jsonb, '{한식,집밥}', '{프라이팬}', 'NaengPago Seed v1', true),
('6a781155-f510-573e-a53f-a2a1dfcd95b2', '두부조림', null, 20, 'EASY', 2, 220, '["두부를 도톰하게 썰어 소금을 뿌리고 물기를 뺀다.","팬에 기름을 두르고 두부를 노릇하게 지진다.","간장, 고춧가루, 다진 마늘로 양념장을 만든다.","두부에 양념장과 물을 붓고 중약불에서 조린다.","국물이 자작해지면 어슷 썬 대파를 올려 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('89017298-4e7a-5b0b-aa46-74bfacc3c95d', '감자조림', null, 25, 'EASY', 2, 200, '["감자를 한입 크기로 썰어 찬물에 헹궈 전분을 뺀다.","팬에 감자와 간장, 물을 넣고 중불에서 끓인다.","감자가 절반쯤 익으면 올리고당을 넣는다.","국물이 졸아들 때까지 조리며 윤기를 낸다.","깨를 뿌려 마무리한다."]'::jsonb, '{집밥}', '{냄비}', 'NaengPago Seed v1', true),
('f8ec7372-3bd3-586b-af7d-f96ac3dd2d61', '연근조림', null, 30, 'NORMAL', 2, 180, '["연근을 껍질을 벗겨 얇게 썰고 식초물에 담근다.","끓는 물에 연근을 살짝 데쳐 아린 맛을 뺀다.","팬에 연근과 간장, 물을 넣고 중불에서 조린다.","국물이 반쯤 졸면 올리고당을 넣어 윤기를 낸다.","깨를 뿌려 마무리한다."]'::jsonb, '{한식,집밥}', '{냄비}', 'NaengPago Seed v1', true),
